# window-lint: allow-file inherits console: developer/worker CLI run from a console, from check.ps1 or from a Bazel test; the children share its (possibly hidden) console
"""Publish a launch set generated by the private VSHELL memory worker.

Standard library only. The worker never writes files; prepared bytes travel
over a private pipe and are published only after all four outputs are present.
"""
import argparse
import ctypes
from ctypes import wintypes
import datetime as dt
import hashlib
import json
from pathlib import Path
import re
import shutil
import struct
import subprocess
import tempfile

NAMES = ("script.dat", "MISSION.STR", "mission.var", "player.mec")
SAVE_OUTPUT = "output.sav"
EXE_HASH = "1534aa8f732bdecd826484d893ad58b8a5e6ebd4d25ab3158a2469b8f69ba16e"
DEFAULT_WORKER = Path(__file__).resolve().parents[3] / ("build/bazel/shell-invitro/"
                      "execroot/_main/bazel-out/x86_windows-fastbuild/bin/"
                      "tools/reference-game/shell-invitro/es2shellprep.exe")


def sha(data):
    return hashlib.sha256(data).hexdigest()


def decode_packet(data):
    """Reject partial, oversized and trailing pipe data before publication."""
    if data[:4] != b"ES2P":
        raise ValueError("worker did not return an ES2P packet")
    cursor = 4

    def block(limit):
        nonlocal cursor
        if len(data) - cursor < 4:
            raise ValueError("truncated packet length")
        size, = struct.unpack_from("<I", data, cursor)
        cursor += 4
        if size == 0 or size > limit or size > len(data) - cursor:
            raise ValueError("invalid packet block length")
        value = data[cursor:cursor + size]
        cursor += size
        return value

    metadata = json.loads(block(16384))
    outputs = {name: block(16 * 1024 * 1024) for name in NAMES}
    # --emit-save appends the SAV written by the original writers; it is
    # proof data for generated saves, never a launch file.
    if metadata.get("emitted_save"):
        outputs[SAVE_OUTPUT] = block(1024 * 1024)
    if cursor != len(data) or len(outputs["mission.var"]) != 2000:
        raise ValueError("packet trailing data or invalid variable bank size")
    return metadata, outputs


def generate(worker, arguments):
    worker = Path(worker).resolve()
    worker_hash = sha(worker.read_bytes())
    with subprocess.Popen([str(worker), *map(str, arguments), "--pipe"],
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE) as process:
        created, exited, kernel, user = (wintypes.FILETIME() for _ in range(4))
        times = ctypes.WinDLL("kernel32", use_last_error=True).GetProcessTimes
        times.argtypes = [wintypes.HANDLE] + [ctypes.POINTER(wintypes.FILETIME)] * 4
        if not times(wintypes.HANDLE(int(process._handle)), ctypes.byref(created),
                     ctypes.byref(exited), ctypes.byref(kernel), ctypes.byref(user)):
            process.kill()
            raise OSError(ctypes.get_last_error(), "GetProcessTimes(worker)")
        ticks = created.dwLowDateTime + (created.dwHighDateTime << 32)
        started = (dt.datetime(1601, 1, 1, tzinfo=dt.timezone.utc) +
                   dt.timedelta(microseconds=ticks // 10)).isoformat()
        try:
            stdout, stderr = process.communicate(timeout=60)
        except subprocess.TimeoutExpired:
            process.kill()
            process.communicate()
            raise
        diagnostics = stderr.decode("utf-8", errors="replace")
        if process.returncode:
            raise RuntimeError(f"worker exited {process.returncode}: {diagnostics.strip()}")
        identity = dict(exe=str(worker), pid=process.pid, process_start_utc=started,
                        process_start_filetime=ticks)
    if sha(worker.read_bytes()) != worker_hash:
        raise RuntimeError("worker executable changed during generation")
    metadata, outputs = decode_packet(stdout)
    resources = []
    for line in diagnostics.splitlines():
        match = re.fullmatch(r"RESOURCE (.+) (\d+) ([0-9a-f]{64})", line)
        if match:
            resources.append(dict(file=match[1], size=int(match[2]), sha256=match[3]))
    provenance = dict(kind="generated-vshell", vshell_sha256=EXE_HASH,
                      worker_sha256=worker_hash, process=identity,
                      arguments=list(map(str, arguments)),
                      state=metadata, resources=resources)
    return outputs, provenance


def file_entries(outputs):
    return [dict(file=name, size=len(outputs[name]), sha256=sha(outputs[name]))
            for name in NAMES]


def git_ignored(repository, path):
    """True only if git positively reports the path as ignored in repository.

    Launch sets contain prepared CD mission data, so they
    may live inside a repository such as es2-data only where nothing can
    commit them. Any git failure counts as not ignored.
    """
    try:
        result = subprocess.run(["git", "-C", str(repository), "check-ignore", "-q", str(path)],
                                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)
    except (OSError, subprocess.SubprocessError):
        return False
    return result.returncode == 0


def checked_destination(path):
    requested = Path(path).absolute()
    # resolve follows existing junctions/symlinks, including the parent of a
    # new final component. Ancestor checks cover this and other worktrees.
    resolved = requested.resolve()
    # build\installs of any checkout (git ignores build\, so the repository test would let it pass).
    if any(a.name.lower() == "installs" and a.parent.name.lower() == "build" and (a.parent.parent / ".git").exists()
           for a in (resolved, *resolved.parents)):
        raise ValueError("output directory is inside an installation")
    for ancestor in (resolved, *resolved.parents, requested, *requested.parents):
        if (ancestor / ".git").exists() and not git_ignored(ancestor, resolved):
            raise ValueError("output directory is inside a repository and not ignored by it")
    if resolved.exists():
        raise ValueError("launch sets are immutable; output must not exist")
    if not resolved.parent.is_dir():
        raise ValueError("output parent must already exist")
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]*", resolved.name):
        raise ValueError("launch name must contain lowercase letters, digits, _ or -")
    return resolved


def publish_checked(destination, outputs, provenance):
    """Called with an already checked path; recheck before the final rename."""
    destination = checked_destination(destination)
    staging = Path(tempfile.mkdtemp(prefix=".shellprep-", dir=destination.parent))
    try:
        write_staging(staging, destination.name, outputs, provenance)
        if checked_destination(destination) != destination:
            raise ValueError("output parent changed during publication")
        # Windows rename refuses an existing destination; there is no overwrite.
        staging.rename(destination)
    finally:
        if staging.exists():
            shutil.rmtree(staging)


def write_staging(directory, name, outputs, provenance):
    """Small separately tested writer; only publish_checked is exposed by CLI."""
    if set(outputs) != set(NAMES) or any(not outputs[n] for n in NAMES):
        raise ValueError("all four nonempty outputs are required")
    manifest = dict(schema=1, name=name,
                    utc=dt.datetime.now(dt.timezone.utc).isoformat(),
                    files=file_entries(outputs), provenance=provenance)
    for filename in NAMES:
        with (directory / filename).open("xb") as stream:
            stream.write(outputs[filename])
    with (directory / "manifest.json").open("x", encoding="utf-8") as stream:
        json.dump(manifest, stream, indent=2)
        stream.write("\n")


def parser():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--worker", type=Path, default=DEFAULT_WORKER)
    p.add_argument("--cd-root", type=Path, required=True)
    p.add_argument("--save", type=Path)
    p.add_argument("--campaign", help="zero-based CAREER group:index")
    p.add_argument("--variables", type=Path, help="exactly 2000 little-endian bank bytes")
    p.add_argument("--seed", type=int, default=0, help="raw original seed word (0..65535; signed-loop semantics)")
    p.add_argument("--language", choices=("E", "F", "G"), default="G")
    p.add_argument("--mode", choices=("0", "1"), help="default: group 0 uses 0, other groups use 1")
    p.add_argument("--difficulty", type=int, default=0, help="shell word 0x4826ea")
    p.add_argument("--training-options", default="0,0,0,0,0", help="bytes at 0x4825c1..c5")
    p.add_argument("--preset-flag", type=int, default=0)
    p.add_argument("--preset-index", type=int, default=0)
    p.add_argument("--output", type=Path, required=True)
    return p


def main():
    p = parser()
    args = p.parse_args()
    try:
        destination = checked_destination(args.output)
        worker_args = ["--cd-root", args.cd_root, "--seed", args.seed,
                       "--language", args.language, "--difficulty", args.difficulty,
                       "--training-options", args.training_options]
        for key in ("save", "campaign", "variables", "mode", "preset_flag", "preset_index"):
            if getattr(args, key) is not None:
                worker_args += ["--" + key.replace('_','-'), getattr(args, key)]
        outputs, provenance = generate(args.worker, worker_args)
        publish_checked(destination, outputs, provenance)
        print(json.dumps(dict(directory=str(destination), files=file_entries(outputs)), indent=2))
    except (ValueError, RuntimeError, OSError, subprocess.TimeoutExpired) as exc:
        p.exit(1, f"es2shellprep: {exc}\n")


if __name__ == "__main__":
    main()
